#!/usr/bin/env python3
from __future__ import annotations
import argparse, json, os, subprocess
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlparse

HTML = '<!doctype html>\n<html lang="fr">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>push_swap — Visualiseur</title>\n<style>\n:root{\n  --bg:#f2efe8; --panel:#fbfaf7; --ink:#171918; --muted:#74756f; --line:#d7d2c8;\n  --a:#243a34; --b:#a86449; --ok:#3f7457;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif}\nbutton,input,textarea{font:inherit}\nbutton{cursor:pointer}\n.wrap{width:min(1450px,calc(100% - 36px));margin:28px auto 44px}\n.head{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:18px}\n.kicker{font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:var(--muted);font-weight:700}\nh1{font:500 clamp(34px,4vw,58px)/1 Georgia,serif;letter-spacing:-.035em;margin:7px 0 0}\n.head-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}\n.tag{border:1px solid var(--line);border-radius:999px;padding:8px 11px;background:#ffffff88;color:var(--muted);font-size:12px}\n.layout{display:grid;grid-template-columns:350px minmax(0,1fr);gap:18px}\n.card{background:var(--panel);border:1px solid var(--line);border-radius:18px}\n.side{padding:18px;display:flex;flex-direction:column;gap:20px}\n.label{font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted);font-weight:750;margin-bottom:8px}\ntextarea,input[type=text],input[type=number]{\n  width:100%;border:1px solid var(--line);border-radius:11px;background:white;color:var(--ink);padding:11px 12px;outline:none\n}\ntextarea{min-height:96px;resize:vertical;font:13px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace}\ntextarea:focus,input:focus{border-color:#9e9c94;box-shadow:0 0 0 3px #424d470f}\n.row{display:flex;gap:8px;flex-wrap:wrap}\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:9px}\n.btn{border:1px solid var(--line);border-radius:11px;background:white;color:var(--ink);padding:10px 13px;font-size:13px;font-weight:700}\n.btn:hover{background:#f4f2ed}.btn.primary{background:var(--ink);color:white;border-color:var(--ink)}\n.note,.status{font-size:12px;line-height:1.55;color:var(--muted)}.status.ok{color:var(--ok)}.status.err{color:#a34539}\n\n.stage{min-height:720px;padding:18px;display:flex;flex-direction:column}\n.stage-head{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:14px;padding:5px 4px 16px;border-bottom:1px solid var(--line)}\n.stack-title{font:500 29px/1 Georgia,serif;display:flex;align-items:baseline;gap:9px}.stack-title.r{justify-content:flex-end}\n.count{font:700 10px/1.2 Inter,system-ui,sans-serif;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}\n.op{text-align:center;min-width:155px}.op small{display:block;font-size:9px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted)}\n.op strong{display:block;font:800 25px/1.2 ui-monospace,SFMono-Regular,Menlo,monospace;margin-top:4px}\n.stacks{display:grid;grid-template-columns:minmax(0,1fr) 62px minmax(0,1fr);gap:10px;flex:1;padding:18px 0 10px}\n.stack{position:relative;display:flex;flex-direction:column;justify-content:flex-end;min-height:500px;border-radius:14px;overflow:hidden;background:linear-gradient(180deg,#ffffff99,#ece8df88)}\n.stack::after{content:"";position:absolute;left:9%;right:9%;bottom:20px;height:1px;background:var(--line)}\n.items{height:100%;display:flex;flex-direction:column;justify-content:flex-end;gap:4px;padding:24px 18px}\n.bar{height:22px;min-height:7px;border-radius:3px;position:relative;transition:width .18s ease}\n.bar.a{background:var(--a);margin-right:auto}.bar.b{background:var(--b);margin-left:auto}\n.bar span{position:absolute;top:50%;transform:translateY(-50%);font-size:10px;font-weight:750;color:var(--ink);white-space:nowrap}\n.bar.a span{left:calc(100% + 8px)}.bar.b span{right:calc(100% + 8px)}\n.mid{display:flex;align-items:center;justify-content:center;position:relative}.mid::before{content:"";width:1px;height:100%;background:linear-gradient(transparent,var(--line) 10%,var(--line) 90%,transparent)}\n.mid span{position:absolute;transform:rotate(-90deg);font-size:9px;letter-spacing:.17em;text-transform:uppercase;color:#989993;background:var(--panel);padding:5px 9px}\n.playback{border-top:1px solid var(--line);padding-top:13px}\n.timeline{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:12px}\n.transport{display:flex;gap:6px}.icon{width:38px;height:38px;border:1px solid var(--line);border-radius:10px;background:white;font-weight:800}.icon.main{background:var(--ink);color:white;border-color:var(--ink)}\ninput[type=range]{width:100%;accent-color:var(--a)}.step{font:12px ui-monospace,SFMono-Regular,Menlo,monospace;color:var(--muted);white-space:nowrap}\n.meta{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap;margin-top:10px;color:var(--muted);font-size:12px}\n.valid{display:flex;align-items:center;gap:7px}.dot{width:8px;height:8px;border-radius:50%;background:#aaa}.dot.ok{background:var(--ok)}.dot.bad{background:#a34539}\n.speed{display:flex;align-items:center;gap:8px}.speed input{width:120px}\n\nbody.capture .side,body.capture .head-actions,body.capture .transport,body.capture .speed{display:none!important}\nbody.capture .layout{grid-template-columns:1fr}\nbody.capture .wrap{width:min(1280px,calc(100% - 44px));margin-top:34px}\nbody.capture .stage{min-height:790px;padding:28px}\nbody.capture .stack{min-height:590px}\nbody.capture .timeline{grid-template-columns:minmax(0,1fr) auto}\nbody.capture h1{font-size:54px}\n.capture-hint{display:none;position:fixed;right:18px;bottom:18px;background:#171918;color:white;padding:9px 12px;border-radius:10px;font-size:12px;opacity:.9}\nbody.capture .capture-hint{display:block}\n\n@media(max-width:900px){.layout{grid-template-columns:1fr}.head{align-items:flex-start;flex-direction:column}.stage{min-height:650px}}\n@media(max-width:620px){.wrap{width:calc(100% - 20px);margin-top:14px}.stage{padding:12px}.stacks{grid-template-columns:minmax(0,1fr) 28px minmax(0,1fr)}.items{padding-left:9px;padding-right:9px}.bar span{display:none}.stack-title{font-size:22px}.op{min-width:80px}.op strong{font-size:20px}}\n</style>\n</head>\n<body>\n<div class="wrap">\n  <header class="head">\n    <div>\n      <div class="kicker">42 · Algorithmique & optimisation</div>\n      <h1>push_swap — visualisation</h1>\n    </div>\n    <div class="head-actions">\n      <span class="tag" id="binaryTag">./push_swap</span>\n      <button class="btn" id="captureBtn" type="button">Mode capture</button>\n    </div>\n  </header>\n\n  <div class="layout">\n    <aside class="card side">\n      <section>\n        <div class="label">Jeu de données</div>\n        <textarea id="numbers" spellcheck="false">42 -17 8 91 3 64 12 -5 77 26 1 55 33 70 19</textarea>\n        <div class="row" style="margin-top:9px">\n          <button class="btn primary" id="runBtn" type="button">Exécuter push_swap</button>\n          <button class="btn" id="exampleBtn" type="button">Exemple</button>\n        </div>\n      </section>\n\n      <section>\n        <div class="label">Génération reproductible</div>\n        <div class="grid2">\n          <label><span class="note">Taille</span><input id="size" type="number" min="2" max="100" value="15"></label>\n          <label><span class="note">Seed</span><input id="seed" type="text" value="portfolio"></label>\n        </div>\n        <button class="btn" id="generateBtn" type="button" style="width:100%;margin-top:9px">Générer</button>\n      </section>\n\n      <section>\n        <div class="label">Capture portfolio</div>\n        <div class="note">Utilise idéalement <strong>10 à 25 valeurs</strong>. Mets en pause quand A et B sont toutes les deux occupées, puis active <strong>Mode capture</strong>.</div>\n      </section>\n\n      <section>\n        <div class="label">État</div>\n        <div class="status" id="status">Prêt.</div>\n      </section>\n    </aside>\n\n    <main class="card stage">\n      <div class="stage-head">\n        <div class="stack-title">Stack A <span class="count" id="countA">0 éléments</span></div>\n        <div class="op"><small>Opération</small><strong id="currentOp">—</strong></div>\n        <div class="stack-title r"><span class="count" id="countB">0 éléments</span> Stack B</div>\n      </div>\n\n      <div class="stacks">\n        <div class="stack"><div class="items" id="stackA"></div></div>\n        <div class="mid"><span>top → bottom</span></div>\n        <div class="stack"><div class="items" id="stackB"></div></div>\n      </div>\n\n      <div class="playback">\n        <div class="timeline">\n          <div class="transport">\n            <button class="icon" id="prevBtn" type="button">‹</button>\n            <button class="icon main" id="playBtn" type="button">▶</button>\n            <button class="icon" id="nextBtn" type="button">›</button>\n          </div>\n          <input id="timeline" type="range" min="0" max="0" value="0">\n          <span class="step" id="stepText">0 / 0</span>\n        </div>\n        <div class="meta">\n          <div class="valid"><span class="dot" id="dot"></span><span id="validText">Aucune exécution</span></div>\n          <div class="speed"><span>Vitesse</span><input id="speed" type="range" min="40" max="650" value="470" step="10"></div>\n        </div>\n      </div>\n    </main>\n  </div>\n</div>\n<div class="capture-hint">Échap pour quitter le mode capture</div>\n\n<script>\n(() => {\n  const $=s=>document.querySelector(s);\n  const e={\n    numbers:$(\'#numbers\'),size:$(\'#size\'),seed:$(\'#seed\'),run:$(\'#runBtn\'),example:$(\'#exampleBtn\'),generate:$(\'#generateBtn\'),\n    status:$(\'#status\'),a:$(\'#stackA\'),b:$(\'#stackB\'),ca:$(\'#countA\'),cb:$(\'#countB\'),op:$(\'#currentOp\'),\n    prev:$(\'#prevBtn\'),next:$(\'#nextBtn\'),play:$(\'#playBtn\'),timeline:$(\'#timeline\'),step:$(\'#stepText\'),speed:$(\'#speed\'),\n    dot:$(\'#dot\'),valid:$(\'#validText\'),capture:$(\'#captureBtn\'),binary:$(\'#binaryTag\')\n  };\n  let source=[],ops=[],states=[],idx=0,timer=null;\n\n  const setStatus=(m,k=\'\')=>{e.status.textContent=m;e.status.className=\'status \'+k};\n\n  function parse(raw){\n    const p=raw.trim().split(/[\\s,;]+/).filter(Boolean);\n    if(p.length<2) throw Error(\'Entre au moins deux nombres.\');\n    const n=p.map(v=>{if(!/^-?\\d+$/.test(v))throw Error(\'Valeur invalide : \'+v);const x=Number(v);if(!Number.isSafeInteger(x)||x<-2147483648||x>2147483647)throw Error(\'Valeur hors int32 : \'+v);return x});\n    if(new Set(n).size!==n.length)throw Error(\'Les doublons ne sont pas autorisés.\');\n    if(n.length>100)throw Error(\'Maximum 100 valeurs pour la visualisation.\');\n    return n;\n  }\n\n  function hash(s){let h=1779033703^s.length;for(let i=0;i<s.length;i++){h=Math.imul(h^s.charCodeAt(i),3432918353);h=h<<13|h>>>19}return()=>{h=Math.imul(h^(h>>>16),2246822507);h=Math.imul(h^(h>>>13),3266489909);return(h^=h>>>16)>>>0}}\n  function rng(a){return()=>{let t=a+=0x6D2B79F5;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296}}\n  function generate(){\n    const n=Math.max(2,Math.min(100,Number(e.size.value)||15)); e.size.value=n;\n    const r=rng(hash(e.seed.value||\'portfolio\')()); const pool=[];\n    for(let i=-n*4;i<=n*4;i++)pool.push(i);\n    for(let i=pool.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}\n    e.numbers.value=pool.slice(0,n).join(\' \');\n  }\n\n  function apply(st,op){\n    const a=st.a.slice(),b=st.b.slice();\n    const sw=s=>{if(s.length>1)[s[0],s[1]]=[s[1],s[0]]};\n    const pu=(f,t)=>{if(f.length)t.unshift(f.shift())};\n    const ro=s=>{if(s.length>1)s.push(s.shift())};\n    const rr=s=>{if(s.length>1)s.unshift(s.pop())};\n    switch(op){\n      case\'sa\':sw(a);break;case\'sb\':sw(b);break;case\'ss\':sw(a);sw(b);break;\n      case\'pa\':pu(b,a);break;case\'pb\':pu(a,b);break;\n      case\'ra\':ro(a);break;case\'rb\':ro(b);break;case\'rr\':ro(a);ro(b);break;\n      case\'rra\':rr(a);break;case\'rrb\':rr(b);break;case\'rrr\':rr(a);rr(b);break;\n      default:throw Error(\'Opération inconnue : \'+op)\n    }\n    return{a,b}\n  }\n\n  function makeStates(nums,operations){const s=[{a:nums.slice(),b:[]}];for(const op of operations)s.push(apply(s[s.length-1],op));return s}\n  function sorted(st){if(st.b.length)return false;for(let i=1;i<st.a.length;i++)if(st.a[i-1]>st.a[i])return false;return true}\n  function width(v){const mn=Math.min(...source),mx=Math.max(...source);return mx===mn?80:22+((v-mn)/(mx-mn))*70}\n\n  function draw(container,arr,cls){\n    container.innerHTML=\'\'; const compact=source.length>28;\n    arr.slice().reverse().forEach(v=>{\n      const d=document.createElement(\'div\');d.className=\'bar \'+cls;d.style.width=width(v)+\'%\';\n      if(compact)d.style.height=Math.max(7,18-Math.floor(source.length/8))+\'px\';\n      const s=document.createElement(\'span\');s.textContent=v;d.appendChild(s);container.appendChild(d);\n    });\n  }\n\n  function render(){\n    if(!states.length)return;\n    idx=Math.max(0,Math.min(idx,ops.length)); const st=states[idx];\n    draw(e.a,st.a,\'a\');draw(e.b,st.b,\'b\');\n    e.ca.textContent=`${st.a.length} élément${st.a.length!==1?\'s\':\'\'}`;e.cb.textContent=`${st.b.length} élément${st.b.length!==1?\'s\':\'\'}`;\n    e.op.textContent=idx===0?\'START\':ops[idx-1];e.timeline.max=ops.length;e.timeline.value=idx;e.step.textContent=`${idx} / ${ops.length}`;\n    const ok=sorted(states[states.length-1]);e.dot.className=\'dot \'+(ok?\'ok\':\'bad\');e.valid.textContent=ok?`Tri validé · ${ops.length} opérations`:\'Résultat non trié\';\n  }\n\n  function stop(){if(timer)clearInterval(timer);timer=null;e.play.textContent=\'▶\'}\n  function play(){if(!states.length||!ops.length)return;if(timer){stop();return}if(idx>=ops.length)idx=0;e.play.textContent=\'Ⅱ\';timer=setInterval(()=>{if(idx>=ops.length){stop();return}idx++;render()},Math.max(40,690-Number(e.speed.value)))}\n\n  async function run(){\n    stop(); let nums;\n    try{nums=parse(e.numbers.value)}catch(err){setStatus(err.message,\'err\');return}\n    e.run.disabled=true;setStatus(\'Exécution de push_swap…\');\n    try{\n      const r=await fetch(\'/api/run\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify({numbers:nums})});\n      const data=await r.json();if(!r.ok||!data.ok)throw Error(data.error||\'Erreur inconnue\');\n      source=nums;ops=data.operations;states=makeStates(source,ops);idx=0;e.binary.textContent=data.binary;render();setStatus(`${ops.length} opérations récupérées.`,\'ok\');\n    }catch(err){setStatus(err.message,\'err\')}finally{e.run.disabled=false}\n  }\n\n  e.generate.addEventListener(\'click\',generate);\n  e.example.addEventListener(\'click\',()=>e.numbers.value=\'42 -17 8 91 3 64 12 -5 77 26 1 55 33 70 19\');\n  e.run.addEventListener(\'click\',run);\n  e.prev.addEventListener(\'click\',()=>{stop();if(idx>0){idx--;render()}});\n  e.next.addEventListener(\'click\',()=>{stop();if(idx<ops.length){idx++;render()}});\n  e.play.addEventListener(\'click\',play);\n  e.timeline.addEventListener(\'input\',()=>{stop();idx=Number(e.timeline.value);render()});\n  e.speed.addEventListener(\'input\',()=>{if(timer){stop();play()}});\n  e.capture.addEventListener(\'click\',()=>{document.body.classList.toggle(\'capture\');e.capture.textContent=document.body.classList.contains(\'capture\')?\'Quitter le mode capture\':\'Mode capture\'});\n  document.addEventListener(\'keydown\',ev=>{\n    if(ev.key===\'Escape\'&&document.body.classList.contains(\'capture\')){document.body.classList.remove(\'capture\');e.capture.textContent=\'Mode capture\'}\n    if([\'INPUT\',\'TEXTAREA\'].includes(document.activeElement.tagName))return;\n    if(ev.key===\'ArrowLeft\'){stop();if(idx>0){idx--;render()}}\n    if(ev.key===\'ArrowRight\'){stop();if(idx<ops.length){idx++;render()}}\n    if(ev.key===\' \'){ev.preventDefault();play()}\n  });\n  generate();run();\n})();\n</script>\n</body>\n</html>\n'

class Handler(BaseHTTPRequestHandler):
    def _json(self,obj,status=200):
        data=json.dumps(obj,ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type","application/json; charset=utf-8")
        self.send_header("Content-Length",str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        if urlparse(self.path).path in ("/","/index.html"):
            data=HTML.encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type","text/html; charset=utf-8")
            self.send_header("Content-Length",str(len(data)))
            self.end_headers()
            self.wfile.write(data)
        else:
            self.send_error(404)

    def do_POST(self):
        if urlparse(self.path).path!="/api/run":
            self.send_error(404); return
        try:
            length=int(self.headers.get("Content-Length","0"))
            body=json.loads(self.rfile.read(length) or b"{}")
            nums=body.get("numbers")
            if not isinstance(nums,list) or not (2<=len(nums)<=100):
                raise ValueError("Utilise entre 2 et 100 valeurs.")
            if any(type(x) is not int for x in nums):
                raise ValueError("Toutes les valeurs doivent être des entiers.")
            if len(set(nums))!=len(nums):
                raise ValueError("Les doublons ne sont pas autorisés.")
            if any(x < -2147483648 or x > 2147483647 for x in nums):
                raise ValueError("Une valeur dépasse la plage int32.")

            binary=self.server.push_swap
            if not binary.is_file():
                raise FileNotFoundError(f"Binaire introuvable : {binary}. Lance d'abord `make`.")
            if not os.access(binary,os.X_OK):
                raise PermissionError(f"Le fichier n'est pas exécutable : {binary}")

            p=subprocess.run([str(binary),*map(str,nums)],cwd=self.server.repo_dir,capture_output=True,text=True,timeout=10)
            if p.returncode!=0:
                raise RuntimeError((p.stderr or p.stdout or "push_swap a retourné une erreur.").strip()[:1500])

            ops=[x.strip() for x in p.stdout.splitlines() if x.strip()]
            allowed={"sa","sb","ss","pa","pb","ra","rb","rr","rra","rrb","rrr"}
            bad=[x for x in ops if x not in allowed]
            if bad:
                raise RuntimeError(f"Sortie inattendue de push_swap : {bad[0]}")

            self._json({"ok":True,"binary":str(binary),"operations":ops,"operation_count":len(ops)})
        except subprocess.TimeoutExpired:
            self._json({"ok":False,"error":"push_swap a dépassé le délai de 10 secondes."},408)
        except (ValueError,FileNotFoundError,PermissionError,RuntimeError) as exc:
            self._json({"ok":False,"error":str(exc)},400)
        except Exception as exc:
            self._json({"ok":False,"error":f"Erreur serveur : {exc}"},500)

    def log_message(self,fmt,*args):
        pass

def main():
    ap=argparse.ArgumentParser(description="Visualiseur local pour 42 push_swap")
    ap.add_argument("--push-swap",default="./push_swap")
    ap.add_argument("--host",default="127.0.0.1")
    ap.add_argument("--port",type=int,default=8765)
    args=ap.parse_args()

    root=Path.cwd().resolve()
    binary=Path(args.push_swap)
    if not binary.is_absolute():
        binary=(root/binary).resolve()

    srv=ThreadingHTTPServer((args.host,args.port),Handler)
    srv.push_swap=binary
    srv.repo_dir=root

    print(f"push_swap : {binary}")
    print(f"Visualiseur : http://localhost:{args.port}")
    print("Ctrl+C pour arrêter.")
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        print("\nArrêt.")
    finally:
        srv.server_close()

if __name__=="__main__":
    main()
